                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_POP && Nat.eqb i 1 && Nat.eqb j 2 && Nat.ltb 53 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CC.has_cell (CC.cp_know c) KZF
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 4256 1 (nth i G.BLS []) (nth i FFS []) POP_W NEWS_V (Some XE) c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => (Z.eqb (CH2.ci_csp ci) (-160) && Nat.eqb (CH2.ci_nx ci) 65)%bool | None => false end
                                  && CL.ps_reg_is ps 10 PE && has cells (KWord (SA FE 120) 8 FLE) && CBA.has_range cells (EVar 34) 1 1024)%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_VISIT then      (* [comment removed for export] *)
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_VISIT && Nat.eqb i 2 && Nat.eqb j 5 && Nat.ltb 66 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && CHA.frames_eqb (nth j FFS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI XKA.VIS 0 (nth i G.BLS []) (nth i FFS []) WENC NEWS_F (Some (ELit 1)) c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-160) | None => false end
                                  && has cells (KWord (SA FE 120) 8 FLE) && CBA.has_range cells XE KIND KIND && CL.ps_reg_is ps 10 VE
                                  && has cells (KZero (SA (CHA.SRL3 VE) SBz) (ELit 51)) && has cells (KZero (SA (CHA.SRL3 S2E) SBz) (ELit 3))
                                  && CBA.has_range cells (EVar 34) 1 1024)%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_ERRH then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_ERRH && Nat.ltb 53 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 16 0 (nth i G.BLS []) (nth i FFS []) [] NEWS_F (Some (ELit 0)) c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-160) | None => false end
                                  && has cells (KWord (SA FE 120) 8 FLE)
                                  && ((Nat.eqb i 1 && Nat.eqb j 3 && CC.has_cell (CC.cp_know c) KZF && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD FE (ELit 64)) && has cells (KWord (SA FE 64) 4 (ELit EL))
                                         && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 8)) 1 (ELit 4)) && CBA.has_range cells (EVar 34) 0 0)
                                      || (Nat.eqb i 2 && Nat.eqb j 4 && Nat.ltb 66 (CC.cp_nx c) && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD FE (ELit 48)) && has cells (KWord (SA FE 48) 4 (ELit EO))
                                         && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 6)) 1 (ELit 4)) && CBA.has_range cells XE OTHERK OTHERK)
                                      || (Nat.eqb i 2 && Nat.eqb j 6 && Nat.ltb 66 (CC.cp_nx c) && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD FE (ELit 32)) && has cells (KWord (SA FE 32) 4 (ELit EL))
                                         && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 4)) 1 (ELit 4)))))%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_SETEC then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_SETEC && ((Nat.eqb i 3 && Nat.eqb j 7) || (Nat.eqb i 4 && Nat.eqb j 8) || (Nat.eqb i 6 && Nat.eqb j 9)) && Nat.ltb 66 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 1024 0 (nth i G.BLS []) (nth i FFS []) SETEC_W NEWS_F None c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-160) | None => false end
                                  && CL.ps_reg_is ps 10 EE && CL.ps_reg_is ps 11 (ELit (ecode i)) && has cells (KWord (SA FE 120) 8 FLE))%bool
                    | None => false end
        | None => false end
      else
        (CBA.exit_base_chk GT.NF RETPC c ps && Nat.ltb 66 (CC.cp_nx c)
         && match CHA.retire_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS []) with Some fle => expr_eqb fle FLE | None => false end
         && has cells (KWord (SA FLE 0) 1 (ELit 0)) && CBA.regions_eqb (CC.cp_F c) CPF4
         && ((Nat.eqb i 5 && has cells (KWord (SA PE 211) 1 (ELit 1)) && has cells (KWord (SA PE 144) 4 (EAlu Instr.ALU_ADD (EVar 34) (ELit (-1)))) && CBA.has_range cells XE KIND KIND
                 && ((has cells (KWord (SA PE 208) 1 (ELit 2)) && CBA.has_range cells (EVar 34) 1 1) || (has cells (KWord (SA PE 208) 1 (ELit 7)) && CBA.has_range cells (EVar 34) 2 1024)))
             || (Nat.eqb i 7 && has cells (KWord (SA PE 211) 1 (ELit 0)) && has cells (KWord (SA PE 144) 4 (EVar 34)) && has cells (KWord (SA PE 208) 1 (EVar 35)) && CBA.has_range cells (EVar 34) 0 0)
             || ((Nat.eqb i 8 || Nat.eqb i 9) && has cells (KWord (SA PE 211) 1 (ELit 0)) && has cells (KWord (SA PE 144) 4 (EVar 34)) && has cells (KWord (SA PE 208) 1 XE) && CBA.has_range cells (EVar 34) 1 1024)))%bool
  end.
